import{_ as t,o,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse('{"title":"Envelope Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/allocations.md","filePath":"reference/tools/allocations.md"}'),d={name:"reference/tools/allocations.md"};function s(c,e,n,l,i,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="envelope-tools" tabindex="-1">Envelope Tools <a class="header-anchor" href="#envelope-tools" aria-label="Permalink to &quot;Envelope Tools&quot;">​</a></h1><p>All envelope tools require <strong>Manager or Owner</strong> role unless noted. See <a href="/reference/concepts/allocations.html">Envelopes</a> for conceptual background.</p><hr><h2 id="allocate_hours" tabindex="-1">allocate_hours <a class="header-anchor" href="#allocate_hours" aria-label="Permalink to &quot;allocate_hours {#allocate_hours}&quot;">​</a></h2><p>Create a per-person hour envelope on a project.</p><p><strong>Writes to</strong>: <code>07. Budgets</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code> or <code>user_slack_id</code></td><td>✅</td><td>Person receiving the envelope</td></tr><tr><td><code>allocated_hours</code></td><td>✅</td><td>Hours for this envelope</td></tr><tr><td><code>task_id</code> or <code>task_name</code></td><td></td><td>Optional work-category tag</td></tr></tbody></table><p><strong>Returns:</strong> envelope <code>id</code> (use for updates/cancellations), and <code>overbooked: true</code> if the person is over capacity.</p><p>If <code>overbooked: true</code> is returned, always surface the warning: &quot;⚠️ [Name] is overbooked by Xh.&quot;</p><p><strong>Both word orders accepted:</strong> <code>allocate 20h to Apex for Rachel as Design</code> (natural: <code>to &lt;project&gt; for &lt;person&gt;</code>) and <code>allocate 20h to Rachel on Apex for Design</code> (legacy: <code>to &lt;person&gt; on &lt;project&gt;</code>) resolve identically. VERA binds each name to the slot matching what it actually is — no re-asking when all slots are present.</p><hr><h2 id="update_allocation" tabindex="-1">update_allocation <a class="header-anchor" href="#update_allocation" aria-label="Permalink to &quot;update_allocation {#update_allocation}&quot;">​</a></h2><p>Change the hours or task on an existing envelope.</p><p><strong>Updates</strong>: <code>07. Budgets</code> col D (hours), col I (task)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>allocation_id</code></td><td>✅</td><td>The envelope&#39;s ID</td></tr><tr><td><code>new_allocated_hours</code></td><td></td><td>New hours value</td></tr><tr><td><code>new_task_id</code> or <code>new_task_name</code></td><td></td><td>New task category</td></tr></tbody></table><p>To find the envelope ID, call <code>get_allocations</code> or <code>get_person_allocation_summary</code> first.</p><p><strong>Restrictions:</strong> Cannot target a Retainer or Agile parent project — envelopes must reference the active period or sprint child. The error message names the active period to guide the user.</p><p><strong>Audit:</strong> The audit message shows exactly what changed (e.g. &quot;40h → 50h&quot; or &quot;task: Design → Development&quot;).</p><p><strong>Deterministic routing (M-ENV-U):</strong> Natural language like &quot;update Sarah&#39;s envelope on Acme to 50h&quot; resolves the target envelope directly from the entity pipeline. If the envelope resolves unambiguously and new hours are present, VERA shows a before→after confirm gate (&quot;Change … (40h) to 50h? Reply 1 to confirm.&quot;) — no model round-trip. If the user holds two envelopes on the same project (e.g. Design + Development), VERA shows a numbered disambiguation menu; the model never picks the candidate.</p><hr><h2 id="cancel_allocation" tabindex="-1">cancel_allocation <a class="header-anchor" href="#cancel_allocation" aria-label="Permalink to &quot;cancel_allocation {#cancel_allocation}&quot;">​</a></h2><p>Mark an envelope as cancelled. The record is kept for audit purposes. Cancellation is terminal — VERA does not track lineage between a cancelled envelope and any replacement.</p><p><strong>Updates</strong>: <code>07. Budgets</code> col F (status → <code>&quot;cancelled&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>allocation_id</code></p><p><strong>Deterministic routing (M-ENV-D):</strong> Natural language like &quot;cancel Sarah&#39;s envelope on Acme&quot; resolves and always shows a terminal confirm gate (&quot;Cancel … ? This is terminal — reply 1 to confirm.&quot;) before executing. Ambiguous → disambiguation menu. The model never cancels without explicit user confirmation.</p><hr><h2 id="reactivate_allocation" tabindex="-1">reactivate_allocation <a class="header-anchor" href="#reactivate_allocation" aria-label="Permalink to &quot;reactivate_allocation {#reactivate_allocation}&quot;">​</a></h2><p>Restore a cancelled envelope to active. Use when an envelope was cancelled by mistake.</p><p><strong>Updates</strong>: <code>07. Budgets</code> col F (status → <code>&quot;active&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>allocation_id</code></p><p>No uniqueness check is performed — multiple active envelopes for the same user/project/task are allowed.</p><p><strong>Audit:</strong> <code>♻️</code></p><p><strong>Deterministic routing (M-ENV-D undo):</strong> Natural language like &quot;reactivate Sarah&#39;s envelope on Acme&quot; fires instantly when the cancelled envelope resolves unambiguously — no confirm gate (non-destructive). Ambiguous → disambiguation menu; the digit fires the reactivation directly. No model invocation.</p><hr><h2 id="get_allocations" tabindex="-1">get_allocations <a class="header-anchor" href="#get_allocations" aria-label="Permalink to &quot;get_allocations {#get_allocations}&quot;">​</a></h2><p>List envelopes with optional filters.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>03. Users</code>, <code>02. Projects</code>, <code>05. Tasks</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>user_id</code></td><td>Filter by person</td></tr><tr><td><code>project_id</code></td><td>Filter by project</td></tr><tr><td><code>status</code></td><td><code>&quot;active&quot;</code> (default) or <code>&quot;cancelled&quot;</code></td></tr><tr><td><code>include_usage</code></td><td><code>&quot;true&quot;</code> to add usage enrichment (see below). Default omits it.</td></tr></tbody></table><p><strong>Returns</strong>: Each allocation includes <code>user_name</code>, <code>project_name</code>, and <code>task_name</code> (the resolved task label, or <code>null</code> if no task is tagged).</p><p>When <code>include_usage=true</code>, each allocation additionally includes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>allocation_id</code></td><td>Same as <code>id</code>, included for renderer parity with <code>get_person_allocation_summary</code></td></tr><tr><td><code>display_project_id</code> / <code>display_project_name</code></td><td>The parent project for retainer/agile period children, otherwise the project itself</td></tr><tr><td><code>project_deadline</code></td><td>The period&#39;s <code>period_end</code>, or the project&#39;s <code>deadline</code>, or the parent&#39;s <code>deadline</code></td></tr><tr><td><code>hours_logged</code></td><td>Hours logged against this envelope&#39;s user/project/task to date</td></tr><tr><td><code>budget_remaining</code></td><td><code>allocated_hours − hours_logged</code> (not floored — negative values are meaningful)</td></tr><tr><td><code>pct_used</code></td><td><code>round(hours_logged / allocated_hours × 100)</code>, or <code>null</code> if <code>allocated_hours</code> is <code>0</code> and hours have been logged</td></tr><tr><td><code>project_status</code></td><td>The status (<code>active</code>, <code>cancelled</code>, <code>completed</code>, etc.) of the display project (parent for retainer/agile periods, otherwise the project itself)</td></tr></tbody></table><p>Used by the web console&#39;s top-level Envelopes overview (<code>/console/envelopes</code>).</p><hr><h2 id="get_my_allocations" tabindex="-1">get_my_allocations <a class="header-anchor" href="#get_my_allocations" aria-label="Permalink to &quot;get_my_allocations {#get_my_allocations}&quot;">​</a></h2><p>The requesting user&#39;s active envelopes.</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="get_my_assignments" tabindex="-1">get_my_assignments <a class="header-anchor" href="#get_my_assignments" aria-label="Permalink to &quot;get_my_assignments {#get_my_assignments}&quot;">​</a></h2><p>&quot;What should I work on?&quot; — returns active envelopes for the requesting user with remaining hours.</p><p>This is the primary tool for Users to understand their current workload. It shows:</p><ul><li>Projects they&#39;re allocated to</li><li>Hours allocated vs. hours logged</li><li>Hours remaining in each envelope</li></ul><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><blockquote><p>Any active user. Assignment = having an active envelope. Anyone can log time to any project regardless of assignment — envelopes are a planning tool, not a gate.</p></blockquote><hr><h2 id="get_project_assignments" tabindex="-1">get_project_assignments <a class="header-anchor" href="#get_project_assignments" aria-label="Permalink to &quot;get_project_assignments {#get_project_assignments}&quot;">​</a></h2><p>Who is allocated to a project. <strong>Manager/Owner.</strong></p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>03. Users</code></p><p><strong>Returns</strong>: user_id, user_name, allocated_hours, hours_logged, hours_remaining, task_id (if tagged), status</p><p><strong>Permission</strong>: Owners see all. Managers see only their assigned projects.</p><hr><h2 id="get_person_allocation_summary" tabindex="-1">get_person_allocation_summary <a class="header-anchor" href="#get_person_allocation_summary" aria-label="Permalink to &quot;get_person_allocation_summary {#get_person_allocation_summary}&quot;">​</a></h2><p>All envelopes for one person across all their projects.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>02. Projects</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code></p><p><strong>Returns per envelope</strong>: project_name, allocated_hours, hours_logged, hours_remaining, status, overdraw flag</p><hr><h2 id="get_project_allocation_summary" tabindex="-1">get_project_allocation_summary <a class="header-anchor" href="#get_project_allocation_summary" aria-label="Permalink to &quot;get_project_allocation_summary {#get_project_allocation_summary}&quot;">​</a></h2><p>All envelopes for one project.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>03. Users</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code></p><hr><h2 id="get_team_availability" tabindex="-1">get_team_availability <a class="header-anchor" href="#get_team_availability" aria-label="Permalink to &quot;get_team_availability {#get_team_availability}&quot;">​</a></h2><p>Remaining hours per person across all active envelopes.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>01. Time Entries</code>, <code>03. Users</code></p><p><strong>Returns per person</strong>: available_hours, allocated_hours, remaining_hours, overbooked flag</p><p>Use this for a quick capacity snapshot before adding new work.</p><hr><h2 id="get_estimates_vs_actuals" tabindex="-1">get_estimates_vs_actuals <a class="header-anchor" href="#get_estimates_vs_actuals" aria-label="Permalink to &quot;get_estimates_vs_actuals {#get_estimates_vs_actuals}&quot;">​</a></h2><p>Compare allocated hours (the plan) against logged hours (the actuals).</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>week_start</code></td><td><code>&quot;this week&quot;</code>, <code>&quot;last week&quot;</code>, or <code>YYYY-MM-DD</code></td></tr><tr><td><code>user_name</code></td><td>Optional — filter to one person</td></tr><tr><td><code>project_name</code></td><td>Optional — filter to one project</td></tr></tbody></table><p><strong>Returns</strong>: per person/project: allocated_hours, actual_hours, delta</p><ul><li><code>delta &gt; 0</code> = over plan (more hours worked than allocated)</li><li><code>delta &lt; 0</code> = under plan (fewer hours than allocated)</li></ul><p>Surface meaningful divergences (delta ≥ ±20%) as insights. Never show estimates vs actuals for future weeks — redirect to <code>get_allocations</code> instead.</p><hr><h2 id="check_capacity" tabindex="-1">check_capacity <a class="header-anchor" href="#check_capacity" aria-label="Permalink to &quot;check_capacity {#check_capacity}&quot;">​</a></h2><p>Can the team absorb new work? Takes discipline requirements and a timeline.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>discipline_requirements</code></td><td>Array of <code>{discipline, hours_needed}</code></td></tr><tr><td><code>start_date</code></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>end_date</code></td><td><code>YYYY-MM-DD</code></td></tr></tbody></table><p><strong>Returns per discipline:</strong></p><ul><li><code>fte_sufficient</code>: FTE has headroom — names and available hours</li><li><code>fte_partial</code>: FTE bench partially covers — gap amount</li><li><code>contractor_required</code>: No FTE capacity — hours of contractor coverage needed</li><li>Contractor conflicts flagged if any contractors are double-booked</li></ul><hr><h2 id="get_capacity_forecast" tabindex="-1">get_capacity_forecast <a class="header-anchor" href="#get_capacity_forecast" aria-label="Permalink to &quot;get_capacity_forecast {#get_capacity_forecast}&quot;">​</a></h2><p>N-week rolling capacity outlook.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>weeks</code></td><td>Number of weeks to forecast (default 4, max 12)</td></tr></tbody></table><p><strong>Returns per week:</strong></p><ul><li>week_start, utilisation_percent, unallocated_hours</li><li>uncovered_projects: projects with no one allocated that week</li><li>overbooked users: name + hours over</li></ul><p><strong>Interpretation:</strong></p><ul><li>&lt; 70% utilisation → plenty of headroom</li><li>70–90% → healthy</li><li><blockquote><p>90% → nearly full, be careful</p></blockquote></li><li>uncovered_projects → flag immediately — no coverage that week</li></ul>',104)])])}const g=t(d,[["render",s]]);export{h as __pageData,g as default};
